from pathlib import Path
import json
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

folder = Path(__file__).resolve().parent
start, end = 61013.0, 61014.0

def read_series(label):
    path = folder / f'Jan_Deca_120925_SH_1_evo_{label}_20251001T00.dat'
    rows = [line.split() for line in path.read_text().splitlines()
            if line.strip() and not line.startswith('#')]
    a = np.array([[float(r[0]), float(r[2]), float(r[5]),
                   float(r[7]), float(r[8]), float(r[9])]
                  for r in rows])
    a = np.column_stack([a, np.linalg.norm(a[:, 3:6], axis=1)])
    inside = (a[:, 0] > start) & (a[:, 0] < end)
    endpoints = [np.array([t] + [np.interp(t, a[:, 0], a[:, i])
                                for i in range(1, a.shape[1])])
                 for t in [start, end]]
    return np.vstack([endpoints[0], a[inside], endpoints[1]])

full = read_series('3I-Atlas1')
ambient = read_series('3I-Atlas2amb')
trap = getattr(np, 'trapezoid', np.trapz)
summary = {}
for name, a in [('full', full), ('ambient', ambient)]:
    summary[name] = {}
    for field, col in [('speed_km_s', 6), ('N_cm_minus3', 2), ('R_AU', 1)]:
        v = a[:, col]
        summary[name][field] = {'time_mean': float(trap(v, a[:, 0])),
                                'min': float(v.min()), 'max': float(v.max())}
    summary[name]['at_utc_hours'] = {
        str(h): {'speed_km_s': float(np.interp(start+h/24, a[:, 0], a[:, 6])),
                 'N_cm_minus3': float(np.interp(start+h/24, a[:, 0], a[:, 2]))}
        for h in [0, 6, 12, 18, 24]}
summary['notes'] = ['UTC day 2025-12-04; boundary values linearly interpolated.',
                    'Speed is magnitude of reported HEEQ-RTN velocity; not comet-relative.',
                    'N is the number-density variable reported in the source header.',
                    'Daily ranges are temporal variation, not confidence intervals.']
(folder/'day_summary.json').write_text(json.dumps(summary, indent=2))
print(json.dumps(summary, indent=2))

plt.rcParams.update({'font.family': 'DejaVu Sans', 'font.size': 10,
                     'axes.spines.top': False, 'axes.spines.right': False})
fig, axes = plt.subplots(2, 1, figsize=(9, 5.5), sharex=True)
for ax, col, ylabel in [(axes[0], 6, 'Wind speed (km/s)'),
                       (axes[1], 2, 'Number density, N (cm⁻³)')]:
    ax.plot((full[:, 0]-start)*24, full[:, col], color='#1565a8', lw=2.4,
            label='Including CMEs')
    ax.plot((ambient[:, 0]-start)*24, ambient[:, col], color='#c66b20',
            lw=1.4, linestyle='--', label='Ambient comparison')
    ax.set_ylabel(ylabel)
    ax.grid(axis='both', color='#e3e8ed', linewidth=.7)
    ax.set_axisbelow(True)
axes[0].legend(loc='upper left', frameon=False, ncol=2)
axes[1].set_xlim(0, 24)
axes[1].set_xticks(range(0, 25, 3), [f'{h:02}:00' for h in range(0, 25, 3)])
axes[1].set_xlabel('4 December 2025 — UTC (24:00 is 5 December 00:00)')
fig.suptitle('Modelled solar wind at 3I/ATLAS', fontsize=17, x=.115, ha='left')
fig.text(.115, .915, 'WSA–ENLIL | Jan_Deca_120925_SH_1 | Heliocentric distance 1.88–1.90 AU',
         color='#53616c', fontsize=10)
fig.text(.115, .025, 'These curves show modelled variation through the day, not observational uncertainty.',
         fontsize=9, color='#53616c')
fig.subplots_adjust(left=.115, right=.97, top=.86, bottom=.13, hspace=.19)
fig.savefig(folder/'solar_wind_3I_ATLAS_2025-12-04.png', dpi=180)

